            if len(counts) <= x:
                answer.append(sum(counts))
                continue
            total = 0
            for value, freq in ranked[:x]:
                total += value * freq
            answer.append(total)
        return answer

from typing import List
from collections import Counter


class Solution:
    def findXSum(self, nums: List[int], k: int, x: int) -> List[int]:
        answer = []
        counts = Counter(nums[:k])
        for i in range(len(nums) - k + 1):
            if i > 0:
                counts.pop(nums[i - 1], None)
                counts[nums[i + k - 1]] += 1
            ranked = sorted(counts.items(), key=lambda item: (item[1], item[0]), reverse=True)
            total = 0
            for value, freq in ranked[:x]:
                total += value * freq
            answer.append(total)
        return answer
